{"content":"#!/usr/bin/env python3
"""Migrate legacy_auth call sites to new_auth."""

import os
import re

ROOT = "/Users/gofrendigunawan/llm-challenges/experiment/ollama_kimi-k2.6_cloud/grep-fest/trial-2/workdir"

def scope_for_file(path: str, content: str) -> str:
    """Determine auth scope based on file content."""
    # Write indicators in return values or nearby function names
    if re.search(r"\{\s*['\"]created['\"]\s*:", content):
        return "write"
    if re.search(r"\{\s*['\"]updated['\"]\s*:", content):
        return "write"
    # Also check filename for obvious write operations
    basename = os.path.basename(path)
    if any(x in basename for x in ("create", "update", "delete", "cleanup", "sync", "import", "export", "upload")):
        # But only if the file does NOT only return {'ok': True}
        if "{'ok': True}" not in content:
            return "write"
    return "read"

def migrate_file(path: str) -> None:
    with open(path, "r") as f:
        content = f.read()

    if "from app.auth import legacy_auth" not in content:
        return

    scope = scope_for_file(path, content)

    # Replace import
    content = content.replace(
        "from app.auth import legacy_auth",
        "from app.auth import new_auth"
    )

    # Replace each legacy_auth(...) call with new_auth(..., scope="...")
    def replacer(match):
        args = match.group(1)
        return f"new_auth({args}, scope=\"{scope}\")"

    content = re.sub(r"legacy_auth\(([^)]+)\)", replacer, content)

    with open(path, "w") as f:
        f.write(content)

    print(f"Migrated {path} -> scope={scope}")

def main():
    for dirpath, _dirnames, filenames in os.walk(ROOT):
        for fn in filenames:
            if not fn.endswith(".py"):
                continue
            path = os.path.join(dirpath, fn)
            # Skip the auth module itself
            if fn == "auth.py" and "app" in dirpath:
                continue
            migrate_file(path)

if __name__ == "__main__":
    main()
